func dlpModeToDefaultAction(mode string, capIntcp bool) uint8 {
	switch mode {
	case share.PolicyModeLearn:
		return C.DPI_ACTION_ALLOW
	case share.PolicyModeEvaluate:
		return C.DPI_ACTION_ALLOW
	case share.PolicyModeEnforce:
		if capIntcp {
			return C.DPI_ACTION_DROP
		} else {
			return C.DPI_ACTION_ALLOW
		}
	}
	return C.DPI_ACTION_ALLOW
}

