			singleFiles = append(singleFiles, singles...)
		}

		// CRD
		for _, filter := range profile.FiltersCRD {
			singles := w.getDirAndFileList(pid, res, filter, dirList)
			singleFiles = append(singleFiles, singles...)
		}
	}
	return dirList, singleFiles
