func (w *FileWatch) SendNVProcessAlert(rootPid, ppid int, cid, path, ppath string) {
	w.mux.Lock()
	grp, ok := w.groups[rootPid]
	w.mux.Unlock()
	if !ok {
		log.WithFields(log.Fields{"rootPid": rootPid, "path": path}).Error()
