	}
	var groupName string
	if grp.profile != nil {
		groupName = grp.profile.Group
	}

	rpt := &MonitorMessage{
		ID:        cid,
		Path:      path,
		ProcPid:   ppid, // assuming
		ProcPath:  path,
		ProcPPid:  ppid,
		ProcPPath: ppath,
		Group:     groupName,
		Msg:       fsNvProtectProcAlert,
		Action:    share.PolicyActionDeny,
	}
	w.sendrpt(rpt)
	log.WithFields(log.Fields{"rpt": rpt}).Debug("FMON:")
}

