	"github.com/neuvector/neuvector/share/utils"
)

const retryReadProcMax int = 1

const (
	escalatReported uint = 1 << iota
	reversShReported
	reversShConfirmed
	suspicReported
	dnsTunnelReported
	profileReported
	historyReported
)

type procEventHdr struct {
	what          uint32
	cpu           uint32
	timeStampNano uint64
}

type userNs struct {
	users  map[int]string
	root   int
	uidMin int
}

type procContainer struct {
	id       string
	rootPid  int
	children utils.Set // pid pool from rootPid (major)
	outsider utils.Set // pid pool from outside
	newBorn  int
	userns   *userNs
	startAt  time.Time
	//map of port listened by multiple processes
	portsMap         map[osutil.SocketInfo]*procApp
	checkRemovedPort uint
	fInfo            map[string]*fileInfo
	bPrivileged      bool
	healthCheck      []string
	nvRole           string
}

type procInternal struct {
	pname        string
	ppath        string
	name         string
	path         string
	cmds         []string
	user         string
	pid          int
	ppid         int
	sid          int
	pgid         int
	ruid         int
	euid         int
	retry        int
	inspectTimes uint
	startTime    time.Time
	lastScanTime time.Time
	scanTimes    uint
	reported     uint
	action       string
	riskyChild   bool
	riskType     string
	execScanDone bool // scan mode only
}

type suspicProcInfo struct {
	ingress bool
	msg     string
}

var suspicProcMap map[string]*suspicProcInfo = map[string]*suspicProcInfo{
	"nmap":       {false, "Port Scanner"},
