	"dns2tcpd":   {true, "dns tunneling"},
}

var kubeProcs map[string]int = map[string]int{
	"kubelet":        1,
	"kube-apiserver": 1,
	"hyperkube":      1,
	"k3s":            1, // check if in k3s env
}

var secretMutex sync.RWMutex
var customSecretRegexps []*regexp.Regexp

func SetCustomSecretPatterns(data []byte) {
	var config secrets.SecretPatternConfig
	err := json.Unmarshal(data, &config)
	if err != nil {
		log.WithFields(log.Fields{"err": err}).Error("invalid secret pattern config")
		return
	}

	newPatterns := utils.NewSetFromStringSlice(config.PatternList)
	oldPatterns := utils.NewSet()

	secretMutex.RLock()
	for _, regexp := range customSecretRegexps {
		oldPatterns.Add(regexp.String())
	}
	secretMutex.RUnlock()

	toKeep := newPatterns.Intersect(oldPatterns)
	toAdd := newPatterns.Difference(oldPatterns)
	newRegexps := make([]*regexp.Regexp, 0, toKeep.Cardinality()+toAdd.Cardinality())
	for add := range toAdd.Iter() {
		re, err := regexp.Compile(add.(string))
		if err != nil {
			log.WithFields(log.Fields{"err": err}).Error()
			continue
		}
		newRegexps = append(newRegexps, re)
	}

	secretMutex.Lock()
	for _, regexp := range customSecretRegexps {
		if toKeep.Contains(regexp.String()) {
			newRegexps = append(newRegexps, regexp)
		}
	}
	customSecretRegexps = newRegexps
	secretMutex.Unlock()
}

// Can be called with process that has exited
func (p *Probe) proc2CLUS(proc *procInternal) *share.CLUSProcess {
	var euser string
	ppid, gid, sid, status, _ := osutil.GetProcessPIDs(proc.pid)
	if ppid != -1 {
		euser = p.getUserName(proc.pid, proc.euid)
	} else {
		euser = proc.user
		status = "Exited"
	}

	output := &share.CLUSProcess{
		Name:    proc.name,
		Pid:     uint32(proc.pid),
		PPid:    uint32(proc.ppid),
		PGid:    uint32(gid),
		PSid:    uint32(sid),
		PSid:    uint32(sid),
		RUid:    uint32(proc.ruid),
		EUid:    uint32(proc.euid),
		Root:    proc.euid == 0,
		Cmds:    proc.cmds,
		User:    euser,
		Status:  status,
		StartAt: proc.startTime.UTC().Unix(),
		Action:  proc.action,
	}

	return output
}

func clearContainerProcesses(c *procContainer) {
	c.children.Clear()
	c.outsider.Clear()
}

func isContainerProcess(c *procContainer, pid int) bool {
	return c.children.Contains(pid) || c.outsider.Contains(pid)
}

// check if the process is assigned to host before. if so, remove from host
func (p *Probe) removeHostPool(pid int) {
	if c, ok := p.containerMap[""]; ok {
		c.children.Remove(pid)
	}
}

func (p *Probe) addProcessPool(pid, ppid int) (*procContainer, bool) {
	if c, ok := p.pidContainerMap[ppid]; ok && c.id != "" {
		if c.children.Contains(ppid) {
			c.children.Add(pid)
		} else {
			c.outsider.Add(pid)
		}
		p.removeHostPool(pid)
		return c, true
	}
	return nil, false
}

// ///
func (p *Probe) isDockerDaemonProcess(proc *procInternal, id string) bool {
	if id == "" { // host porcesses
		if global.RT.IsRuntimeProcess(proc.pname, nil) {
			// skip: runtime processes
			return true
		}

		if p.bKubePlatform {
			if _, ok := kubeProcs[proc.pname]; ok {
				// skip: kube processes
				return true
			}
		}
	}
	return proc.name == global.RT.String() || proc.pname == global.RT.String()
}

// //
// scan at timestamp: 0, 2, 4, 8, 16, 24, 32
// after 1 minute, it scans once every minute
