// // Modern shell commands and their paths
// // handle the real path later as needed
var commonShellName map[string]string = map[string]string{
	"bash": "/bin/bash",
	"sh":   "/bin/sh",
	"ash":  "/bin/ash",
	"dash": "/bin/dash",
	"csh":  "/bin/csh",
	"tcsh": "/bin/tcsh",
}

func (p *Probe) isShellScript(id string, proc *procInternal) int {
	if id != "" { // TODO: could remove and apply to all conatiners later
		return 0
	}

	// a shell command ?
	appname := filepath.Base(proc.path)
	_, ok := commonShellName[appname] // subpath
	if !ok {
		// Two expected escaping shell script cases (false-negative, no harm):
		// (1) 	>> bash psloop.sh
		// 		cmd=[bash psloop.sh ] name=bash path=/bin/bash
		//    	It will be recorded as {"bash", "/bin/bash"}
		// (2) 	>> sh psloops.sh
		// 		cmd=[sh psloop.sh ] name=sh path=/bin/dash
		// 		It will be recorded as {"sh", "/bin/dash"}
		return 0
	}

	// log.WithFields(log.Fields{"path": proc.path, "name": proc.name}).Debug()
	// log.WithFields(log.Fields{"cmd": proc.cmds}).Debug()

	// sample from "Microsoft System Center - Operations Manager"
	// cmd=[/bin/bash server=$1 if [ `systemctl list-unit-files | grep -i "atomic-openshift-master-api.service" | wc -l` -gt 0 ] then /etc/opt/microsoft/scx/conf/tmpdir/scxuPiwXl ocpmaster5102.rbgooe.at ]
	// id=[host] name=scxuPiwXl  path=/usr/bin/bash
	// parent=sudo ppath=/usr/bin/sudo
	for i, cmd := range proc.cmds {
		// log.WithFields(log.Fields{"i": i, "cmd": cmd}).Debug("")
		if i == 0 {
			filename := filepath.Base(cmd)
			if _, ok := commonShellName[filename]; !ok { // not a shell cmd
				return 0 // reject at first entry
				return 0 // reject at first entry
			}
			// entering 2nd screening
			// cmd=[/bin/sh ./1.sh ] name=1.sh path=/bin/dash
			// log.WithFields(log.Fields{"filename": filename}).Debug("")
		} else {
			// could be in any entry, exclude excessive unique names
			// it could be called by: execl(<script-path>, <script-name>, (char *)0);
			if strings.Contains(cmd, proc.name) {
				log.WithFields(log.Fields{"shell": proc.path, "script": cmd}).Debug("found")
				return 1
			}
		}
	}
	return 0
}

// PatchContainerProcess()
// Fixed the missing process table, caused by the netlink recv errors, no process record is available.
// Current patch is only for important init-process of a container
func (p *Probe) PatchContainerProcess(pid int, bEval bool) bool {
	p.lockProcMux()
	defer p.unlockProcMux()
	if _, ok := p.pidProcMap[pid]; !ok {
		now := time.Now()
		proc := &procInternal{
			pid:          pid,
			ppid:         pid, // assume
			sid:          osutil.GetSessionId(pid),
			startTime:    now,
			lastScanTime: now,
			action:       share.PolicyActionAllow,
		}

		// is it a process inside a cgroup
		if c, ok := p.addContainerCandidateFromProc(proc); ok {
			p.updateProcess(proc)
			proc.user = p.getUserName(proc.ppid, proc.euid) // get parent's username
			var err error
			proc.path, err = global.SYS.GetFilePath(proc.pid) // exe path
			if err != nil && !errors.Is(err, os.ErrNotExist) {
				// Log debug: called per process event, skip os.ErrNotExist (common for short-lived processes)
				log.WithError(err).Debug("failed to get process executable path")
			}
			proc.cmds, err = global.SYS.ReadCmdLine(proc.pid)
			if err != nil && !errors.Is(err, os.ErrNotExist) {
				// Log debug: called per process event, skip os.ErrNotExist (common for short-lived processes)
				log.WithError(err).Debug("failed to read process cmdline")
			}
			proc.pname, _, _, _ = osutil.GetProcessUIDs(proc.ppid)
			p.pidProcMap[proc.pid] = proc
			p.addProcHistory(c.id, proc, true)

			if bEval && !p.isDockerDaemonProcess(proc, c.id) {
				go p.evalNewRunningApp(proc.pid) // no sequential issue
			}
			log.WithFields(log.Fields{"proc": proc, "id": c.id}).Debug()
			return true
		}
	}
	return false
}

func isControllerType(role string) bool {
	return role == "controller" || role == "controller+enforcer+manager"
}

func isManagerType(role string) bool {
	return role == "manager" || role == "controller+enforcer+manager"
}

// protected by lock
func (p *Probe) isNVChildProcess(c *procContainer, proc *procInternal) bool {
	var err error
	nvRole := c.nvRole
	if nvRole == "" {
		return false
	}

	ppath := proc.ppath
	path := proc.path
	pid := proc.pid
	ppid := proc.ppid
	bRuncInit := p.isAllowRuncInitCommand("runc", proc.cmds)
	if ppath == "" {
		if ppath, err = global.SYS.GetFilePath(ppid); err != nil {
			log.WithFields(log.Fields{"err": err, "nvRole": nvRole, "ppid": ppid}).Debug()
		}
	}

	if path == "" && pid > 0 {
		if path, err = global.SYS.GetFilePath(pid); err != nil {
			log.WithFields(log.Fields{"err": err, "nvRole": nvRole, "pid": pid}).Debug()
		}
	}

	mLog.WithFields(log.Fields{"path": path, "ppath": ppath, "nvRole": nvRole, "ppid": ppid, "cmds": proc.cmds}).Debug()
	if isManagerType(nvRole) {
		switch path {
		case "/usr/bin/python3.12", "/usr/bin/bash":
			for i, cmd := range proc.cmds {
				if i == 1 {
					switch cmd {
					case "/usr/local/bin/cli", "/usr/local/bin/cli.py":
						c.outsider.Remove(pid)
						c.children.Add(pid)
						return true
					}
				}
				if i > 1 {
					break // not for cli
				}
			}
		}
		return path == ppath /// only for cli case
	}

	bK8sProbeSituation := p.bKubePlatform && isControllerType(nvRole) && ppath == "" // a quick probe process
	// backup lookup if we did not catch its parents
	for i := 0; i < 8; i++ { // lookup for 8 callers
		if global.RT.IsRuntimeProcess(filepath.Base(ppath), nil) || bRuncInit || bK8sProbeSituation || ppid == 1 {
			mLog.WithFields(log.Fields{"path": path, "ppath": ppath, "nvRole": nvRole, "k8s": p.bKubePlatform, "bRuncInit": bRuncInit}).Debug()
			switch path {
			case "/usr/bin/cat": // k8s readiness probe
				if p.bKubePlatform && isControllerType(nvRole) {
					if bRuncInit {
						return true
					} else {
						switch len(proc.cmds) {
						case 2, 3:
							if proc.cmds[1] != "/tmp/ready" {
								return false
							}
							fallthrough
						case 1: // cmdline: polymorphic behavior
							return proc.cmds[0] == "cat"
						}
					}
				}
				return false
			case "/usr/bin/bash": // cli checks
				return isManagerType(nvRole)
			case "/usr/local/bin/monitor":
				return true
			}
			break
		}

		if filepath.Dir(ppath) == "/usr/local/bin" {
			log.WithFields(log.Fields{"caller": ppath}).Debug()
			return true
		}

		if isManagerType(nvRole) {
			switch ppath {
			case "/usr/lib64/jvm/java-17-openjdk-17/bin/java",
				"/usr/lib64/jvm/java-17-openjdk-17/lib/jspawnhelper",
				"/usr/bin/python3.12": // stty
				log.WithFields(log.Fields{"caller": ppath}).Debug()
				return true
			}
		}

		// find its parent
		if proc, ok := p.pidProcMap[ppid]; ok {
			ppid = proc.ppid
		} else {
			if _, ppid, err = global.SYS.GetProcessName(ppid); err != nil || ppid == 0 {
				return false
			}
		}
		if ppath, err = global.SYS.GetFilePath(ppid); err != nil {
			return false
		}
		mLog.WithFields(log.Fields{"caller": ppath, "ppid": ppid, "i": i}).Debug()
	}
	return false
}

