			pp.Mode = grp.ProfileMode
			pp.Baseline = grp.BaselineProfile
			if err := clusHelper.PutProcessProfile(grp.Name, pp); err != nil {
				log.WithFields(log.Fields{"error": err}).Error()
				return err
			}
