			}
			path = pathStr[i+1:]
			if _, _, _, euid = osutil.GetProcessUIDs(pid); euid > 0 {
				user = p.getUserName(1, euid)
			}
			dockerCmds = cmds
			found = true
		}
	}
	return
}

