func (p *Probe) evaluateRuntimeCmd(proc *procInternal) bool {
	if global.RT.IsRuntimeProcess(filepath.Base(proc.ppath), nil) {
		if global.RT.IsRuntimeProcess(filepath.Base(proc.path), nil) {
			return true

