func (w *FileWatch) loop() {

	msgTicker := time.Tick(time.Second * 4)
	// every 10s send learning rules to controller

	learnTicker := time.Tick(time.Second * 10)

	for {
		select {
		case <-msgTicker:
			w.HandleWatchedFiles()
		case <-learnTicker:
			w.reportLearningRules()
		}
	}
}

