				Group:  pp.Group,
				Rule:   *ppe,
			}
			pc.pMap.RuleMap[ppe.Uuid] = pRule
		}
	}

	// release memory
	gone.Clear()
	added.Clear()
	previous.Clear()
	previous, gone, added = nil, nil, nil
}

